mapper.select:
SELECT s.*, ( SELECT count( 1 ) FROM member_room_info WHERE deleted = 0 AND store_id = s.store_id ) roomNum, ( SELECT count( 1 ) FROM member_device_info WHERE deleted = 0 AND store_id = s.store_id ) deviceNum, ( SELECT count( 1 ) FROM member_device_info WHERE deleted = 0 AND STATUS = 1 AND room_id = s.store_id ) deviceOnlineNum FROM member_store_info s left join member_store_user su on su.store_id=s.store_id WHERE s.deleted = 0 and su.user_id=#{userId} and su.type in (12,13)
and locate(#{name},s.store_name)>0
and s.city_name=#{cityName}
